      "reason": "La résolution 2026-03-053, citée page 14 et adoptée page 15, autorise à enchérir et à acquérir lors de la vente du 9 avril 2026, ce qui constitue un acte foncier inclus."
    },
    {
      "item": "i02",
      "choice": "v1",
      "reason": "La résolution 2026-03-057 adopte explicitement page 17 le règlement 2026-503 modifiant les conditions d’émission de permis et certificats concernant des immeubles en zone agricole."
    },
    {
      "item": "i03",
      "choice": "v1",
      "reason": "La résolution 2026-03-058 commence par l’intitulé cité page 17 et adopte page 18 le règlement 2026-501 ajoutant la recherche et le développement en agriculture aux usages commerciaux para-agricoles."
    },
    {
      "item": "i04",
      "choice": "v1",
      "reason": "La page 19 autorise partiellement les modifications du zonage 2019-342 et refuse l’augmentation à 24 logements ainsi que la modification de l’article 6.20, sans adopter encore de règlement modificatif."
    },
    {
      "item": "i05",
      "choice": "v1",
      "reason": "Le plan d’urbanisme 2019-341 est explicitement visé dans la citation page 18 et sa modification est autorisée au point 2 de la résolution page 19, constituant un objet réglementaire distinct du zonage."
    },
    {
      "item": "i06",
      "choice": "v1",
      "reason": "La demande 2026-003 au 1394, boulevard Saint-Jean-Baptiste Ouest est identifiée page 19 puis autorisée page 20 avec mandat de préparer les documents réglementaires, sans adoption d’un règlement."
    },
    {
      "item": "i07",
      "choice": "v1",
      "reason": "La résolution 2026-03-061 identifie page 20 la demande et les deux lots, puis accorde page 21 un appui municipal à la demande CPTAQ plutôt qu’une autorisation de la Commission."
    },
    {
      "item": "i08",
      "choice": "v1",
      "reason": "La page 22 refuse expressément le PIIA pour les panneaux solaires au 182, rue Saint-Joseph, conformément à la règle voulant que les refus restent des refus."
    },
    {
      "item": "i09",
      "choice": "v1",
      "reason": "La résolution 2026-03-063 adoptée page 22 autorise expressément la démolition au 5, rue Phénix et le programme préliminaire de réutilisation du sol comprenant la reconstruction."
    },
    {
      "item": "i10",
      "choice": "v1",
      "reason": "La résolution 2026-03-064 adoptée page 23 exige une contribution monétaire de 7 625,90 $ pour le lot projeté 6 717 037 dans le cadre du lotissement au 330, rang Laberge."
    }
  ]
